/* Shopping membership requests and the private notification inbox. */
(function(){
 'use strict';
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const dates=s=>s?new Date(s).toLocaleString('en-GB',{timeZone:'Asia/Karachi',day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'';
 const labels={pending_admin:'Awaiting admin review',pending_sponsor:'Awaiting sponsor review',awaiting_founder:'Awaiting Founder placement',completed:'Membership complete',declined:'Request declined'};
 const glyph=(shape)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shape}</svg>`;
 const icons={sales:glyph('<path d="M4 7h16l1 14H3zM8 7V5a4 4 0 0 1 8 0v2"/>'),team:glyph('<circle cx="12" cy="5" r="3"/><circle cx="5" cy="19" r="3"/><circle cx="19" cy="19" r="3"/><path d="M12 8v5M5 16v-3h14v3"/>'),community:glyph('<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c5 6 5 12 0 18-5-6-5-12 0-18Z"/>'),rank:glyph('<path d="m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z"/>'),message:glyph('<rect x="3" y="4" width="18" height="14" rx="3"/><path d="m7 18-3 4v-6M7 9h10M7 13h6"/>')};
 function create({db,getSession,go,toast,submit,refreshIdentity}){
  let status=null,messages={rows:[],unread:0,total:0},messageOffset=0,unreadOnly=false,selected='orders',requestVersion=0;
  const queueState=new Map();
  const rpc=async(name,args)=>{const {data,error}=await db.rpc(name,args);if(error)throw error;return data};
  const root=document.querySelector('.shopping-account-content');
  for(const [id,title] of [['shoppingEarn','Ways to earn'],['shoppingMessages','Messages & notifications']]){const panel=document.createElement('section');panel.id=id;panel.hidden=true;panel.setAttribute('aria-label',title);root.append(panel)}
  function select(section){selected=section;document.getElementById('shoppingEarn').hidden=section!=='earn';document.getElementById('shoppingMessages').hidden=section!=='messages';if(section==='earn')renderEarn();if(section==='messages')renderMessages()}
  async function load(){const owner=getSession()?.user.id;if(!owner)return;const turn=++requestVersion;const [membership,inbox]=await Promise.all([rpc('shopping_membership_status'),rpc('shopping_messages',{p_offset:messageOffset,p_unread:unreadOnly})]);if(owner!==getSession()?.user.id||turn!==requestVersion)return;status=membership;messages=inbox;let badge=document.getElementById('shoppingUnreadBadge');if(!badge){badge=document.createElement('b');badge.id='shoppingUnreadBadge';badge.className='shopping-unread-badge';document.querySelector('[data-account-section="messages"]')?.append(badge)}badge.textContent=inbox.unread>99?'99+':String(inbox.unread);badge.hidden=!inbox.unread;select(selected)}
  function renderEarn(){const target=document.getElementById('shoppingEarn');if(!status){target.innerHTML='<p role="status">Loading membership options…</p>';return}
   const r=status.request,waiting=r&&['pending_admin','pending_sponsor','awaiting_founder'].includes(r.status),member=status.is_member;
   const ways=[['sales','01','Share products. Earn on sales.','Promote marketplace products and earn a percentage of eligible sales. The applicable commission depends on the product and current sale rules.','Product sales'],['team','02','Build a team that grows.','Invite people to your network and qualify for direct, generation and team earnings under your membership plan.','Team building'],['community','03','Take part in Community Share.','Meet the active-share qualifications to participate in Community Share distributions. Your dashboard shows eligibility and share status.','Community Share'],['rank','04','Progress through the ranks.','Reach leadership milestones and qualify for the bonuses available at each rank. Rank requirements and rewards follow the current programme.','Rank achievements']];
   target.innerHTML=`<div class="shopping-earn-hero"><span class="eyebrow">EARN WITH MARKET IS ONLINE</span><h2>Your next chapter starts here.</h2><p>Turn product recommendations, teamwork and leadership into earning opportunities.</p><div class="shopping-earn-pills"><span>Product sales</span><span>Team growth</span><span>Leadership</span></div></div><div class="shopping-earning-grid">${ways.map(([key,n,title,copy,label])=>`<article class="shopping-earning-card"><div class="shopping-earning-top"><span>${icons[key]}</span><small>${n}</small></div><span class="eyebrow">${label}</span><h3>${title}</h3><p>${copy}</p></article>`).join('')}</div><p class="shopping-earning-note">Earnings depend on eligible activity, the applicable plan and current programme rules. Membership approval does not activate a paid package or guarantee income.</p><section class="shopping-membership-cta"><div><span class="eyebrow">YOUR MEMBERSHIP</span><h3>${member?'Your member account is ready':waiting?'Your request is in progress':'Ready to become a member?'}</h3><p>${member?'Your shopping orders and payments stay with your existing account.':status.has_sponsor?'Your request goes to '+esc(status.sponsor_name||'your linked sponsor')+' for approval and Left or Right placement.':'You joined without a referral. Ask admin to assign your request to the Founder for review and placement.'}</p>${status.has_sponsor?`<span class="shopping-sponsor-label">Member referral: ${esc(status.member_referral_code)}</span>`:''}</div>${r?`<div class="shopping-request-progress" role="status"><span class="shopping-request-state" data-status="${esc(r.status)}">${labels[r.status]||esc(r.status)}</span><small>Requested ${dates(r.created_at)}</small>${r.status==='awaiting_founder'?'<p>Admin has approved. The Founder will review your request and choose a placement leg.</p>':''}${r.placement_side?`<p>Placement: ${esc(r.placement_side==='LEFT'?'Left':'Right')} leg</p>`:''}${r.review_note?`<p>${esc(r.review_note)}</p>`:''}</div>`:''}${member?'<button class="btn primary" data-shopping-open-member>Open Member Dashboard →</button>':waiting?'<button class="btn" data-shopping-network-refresh>Refresh request status</button>':`<form id="shoppingMembershipRequest" class="form"><label class="shopping-consent"><input type="checkbox" name="consent" required> I request network membership and accept the membership terms.</label><div class="shopping-membership-actions"><button class="btn ${status.has_sponsor?'primary':''}" type="${status.has_sponsor?'submit':'button'}" ${status.has_sponsor?'':'disabled aria-describedby="shoppingDirectMemberHelp"'}>Become a Member</button>${status.has_sponsor?'':'<button class="btn primary" type="submit">Request to Admin →</button>'}</div>${status.has_sponsor?'':'<small id="shoppingDirectMemberHelp">A sponsor must be assigned before you can become a member.</small>'}</form>`}</section>`;
  }
  function renderMessages(){const target=document.getElementById('shoppingMessages');target.innerHTML=`<div class="shopping-message-toolbar"><div><strong>${messages.unread} unread</strong><span>Order, payment and membership updates</span></div><button class="btn small" data-shopping-read-all ${messages.unread?'':'disabled'}>Mark all as read</button></div><label class="shopping-message-filter"><input type="checkbox" data-shopping-unread ${unreadOnly?'checked':''}> Unread only</label><div class="shopping-message-list">${messages.rows.length?messages.rows.map(m=>`<article class="shopping-message ${m.read_at?'':'unread'}"><span class="shopping-message-icon">${icons.message}</span><div><small>${esc(m.category)} · ${dates(m.created_at)}</small><h3>${esc(m.title)}</h3><p>${esc(m.message)}</p><div class="shopping-message-actions"><button type="button" class="btn small" data-shopping-message="${esc(m.id)}">View update →</button>${m.read_at?'':'<button type="button" class="text-button" data-shopping-read="'+esc(m.id)+'">Mark as read</button>'}</div></div>${m.read_at?'':'<span class="shopping-unread-dot" aria-label="Unread"></span>'}</article>`).join(''):'<div class="shopping-account-empty"><span>'+icons.message+'</span><h2>'+(unreadOnly?'You are all caught up':'Your updates will appear here')+'</h2><p>We will keep you informed about your orders, payments and membership requests.</p></div>'}</div>${messages.total>50?`<div class="shopping-order-pagination"><span>Page ${Math.floor(messageOffset/50)+1} of ${Math.ceil(messages.total/50)}</span><div><button class="btn small" data-shopping-message-page="${messageOffset-50}" ${messageOffset?'':'disabled'}>Previous</button><button class="btn small" data-shopping-message-page="${messageOffset+50}" ${messageOffset+50>=messages.total?'disabled':''}>Next</button></div></div>`:''}`}
  async function queue(admin=false){const owner=getSession()?.user.id;if(!owner)return;const key=admin?'admin':'sponsor';let state=queueState.get(key);if(!state){state={filter:'pending',search:'',offset:0,turn:0};queueState.set(key,state)}let target=document.getElementById('shoppingMembershipQueue-'+key);if(!target){target=document.createElement('section');target.id='shoppingMembershipQueue-'+key;target.className='shopping-membership-queue';target.dataset.queueScope=key;const parent=document.getElementById(admin?'control-user-membership':'page-network');if(!parent)return;if(admin)parent.append(target);else parent.prepend(target)}
   const turn=++state.turn;target.setAttribute('aria-busy','true');try{const data=await rpc('shopping_membership_queue',{p_admin:admin,p_status:state.filter,p_search:state.search,p_offset:state.offset});if(getSession()?.user.id!==owner||state.turn!==turn)return;state.data=data;renderQueue(target,state,admin)}catch(error){if(getSession()?.user.id===owner&&state.turn===turn)target.innerHTML='<p role="alert">Requests could not be loaded. <button class="btn" data-membership-refresh>Try again</button></p>';throw error}finally{target.removeAttribute('aria-busy')}}
  function renderQueue(target,state,admin){const d=state.data;target.innerHTML=`<header class="shopping-queue-heading"><div><span class="eyebrow">NETWORK MEMBERSHIP</span><h2>User to Member Requests <span>${d.pending}</span></h2><p>${admin?'Approve direct shoppers and send their requests to the Founder. The Founder completes placement.':'Review your linked Users. Accept a request, then choose Left or Right to complete membership.'}</p></div><button class="btn small" data-membership-refresh>Refresh</button></header><form class="shopping-queue-search"><label>Find a request<input name="search" type="search" maxlength="100" placeholder="Name or email" value="${esc(state.search)}"></label><label>Status<select name="status">${[['pending','Pending requests'],['all','All requests'],['pending_admin','Awaiting admin'],['pending_sponsor','Awaiting sponsor'],['awaiting_founder','Awaiting Founder'],['completed','Completed'],['declined','Declined']].filter(([v])=>admin?v!=='pending_sponsor':v!=='pending_admin').map(([v,t])=>`<option value="${v}" ${v===state.filter?'selected':''}>${t}</option>`).join('')}</select></label><button class="btn" type="submit">Apply filters</button></form><p class="shopping-queue-count" role="status">${d.total} matching ${d.total===1?'request':'requests'}</p><div>${d.rows.length?d.rows.map(r=>{const canReview=admin?r.status==='pending_admin':['pending_sponsor','awaiting_founder'].includes(r.status);return `<details class="shopping-membership-row"><summary><span><strong>${esc(r.full_name)}</strong><small>${esc(r.email)}</small></span><span class="shopping-request-state" data-status="${esc(r.status)}">${labels[r.status]}</span><span class="shopping-request-date">${dates(r.created_at)}</span><span class="shopping-row-open">Review ↓</span></summary><div class="shopping-request-details"><div><p><strong>Phone</strong><span>${esc(r.phone)}</span></p><p><strong>Request route</strong><span>${r.source==='direct'?'Direct customer → Admin → Founder':'Linked User → Sponsor'}</span></p>${r.sponsor_member_code?`<p><strong>Assigned member</strong><span>${esc(r.sponsor_member_code)}</span></p>`:''}${r.placement_side?`<p><strong>Placement</strong><span>${esc(r.placement_side)}</span></p>`:''}${r.review_note?`<p><strong>Review note</strong><span>${esc(r.review_note)}</span></p>`:''}</div>${canReview?`<form class="form shopping-membership-review" data-request="${esc(r.id)}"><label>Decision<select name="decision" required><option value="">Choose a decision</option><option value="accept">Accept${admin?' and send to Founder':''}</option><option value="deny">Deny request</option></select></label>${admin?'':`<label data-placement-field hidden>Placement leg<select name="side" disabled><option value="">Choose Left or Right</option><option value="LEFT">Left leg</option><option value="RIGHT">Right leg</option></select><small>The next available position on this leg is selected using the existing network rules.</small></label>`}<label>Review note<textarea name="note" maxlength="500" rows="2" placeholder="Required when declining"></textarea></label><button class="btn primary" type="submit">${admin?'Save admin decision':'Confirm decision & placement'}</button><p class="shopping-review-status" role="status"></p></form>`:`<p class="shopping-request-done">${r.status==='awaiting_founder'?'Admin review is complete. Only the assigned Founder can complete this placement.':r.status==='completed'?'Membership and placement are complete.':'This request has been reviewed.'}</p>`}</div></details>`}).join(''):'<div class="shopping-account-empty"><h3>No requests here</h3><p>New requests will appear here when a User applies for membership.</p></div>'}</div>${d.total>50?`<div class="shopping-order-pagination"><span>Page ${Math.floor(state.offset/50)+1} of ${Math.ceil(d.total/50)}</span><div><button class="btn small" data-membership-page="${state.offset-50}" ${state.offset?'':'disabled'}>Previous</button><button class="btn small" data-membership-page="${state.offset+50}" ${state.offset+50>=d.total?'disabled':''}>Next</button></div></div>`:''}`}
  document.addEventListener('submit',e=>{const f=e.target;if(!f.matches('#shoppingMembershipRequest,.shopping-membership-review,.shopping-queue-search'))return;e.preventDefault();submit(f,async()=>{if(f.id==='shoppingMembershipRequest'){await rpc('request_shopping_membership',{p_consent:f.elements.consent.checked});await load();toast('Membership request sent');return}const target=f.closest('[data-queue-scope]'),admin=target.dataset.queueScope==='admin';if(f.matches('.shopping-queue-search')){const state=queueState.get(target.dataset.queueScope);state.search=f.elements.search.value.trim();state.filter=f.elements.status.value;state.offset=0;await queue(admin);return}const v=f.elements;if(!v.decision.value)throw Error('Choose Accept or Deny');try{await rpc('review_shopping_membership',{p_request:f.dataset.request,p_approve:v.decision.value==='accept',p_side:admin?null:v.side.value||null,p_note:v.note.value.trim()});await queue(admin);toast('Request decision saved')}catch(error){f.querySelector('[role="status"]').textContent=error.message;throw error}})});
  document.addEventListener('change',e=>{if(e.target.matches('.shopping-membership-review [name="decision"]')){const f=e.target.form,accept=e.target.value==='accept',placement=f.querySelector('[data-placement-field]');if(placement){placement.hidden=!accept;f.elements.side.disabled=!accept;f.elements.side.required=accept}f.elements.note.required=e.target.value==='deny';f.elements.note.minLength=e.target.value==='deny'?3:0}if(e.target.matches('[data-shopping-unread]')){unreadOnly=e.target.checked;messageOffset=0;load().catch(e=>toast(e.message))}});
  document.addEventListener('click',e=>{const b=e.target.closest('[data-shopping-network-refresh],[data-shopping-open-member],[data-shopping-read-all],[data-shopping-read],[data-shopping-message],[data-shopping-message-page],[data-membership-refresh],[data-membership-page]');if(!b)return;submit({querySelector:()=>b},async()=>{if(b.matches('[data-membership-refresh],[data-membership-page]')){const target=b.closest('[data-queue-scope]');if(b.hasAttribute('data-membership-page'))queueState.get(target.dataset.queueScope).offset=Math.max(0,Number(b.dataset.membershipPage));await queue(target.dataset.queueScope==='admin');return}if(b.hasAttribute('data-shopping-open-member')){await refreshIdentity();go('dashboard');return}if(b.hasAttribute('data-shopping-message-page'))messageOffset=Math.max(0,Number(b.dataset.shoppingMessagePage));if(b.hasAttribute('data-shopping-read-all')||b.hasAttribute('data-shopping-read')){await rpc('read_shopping_messages',{p_id:b.dataset.shoppingRead||null});messageOffset=0}if(b.hasAttribute('data-shopping-message')){const m=messages.rows.find(x=>x.id===b.dataset.shoppingMessage);if(!m)return;await rpc('read_shopping_messages',{p_id:m.id});await load();if(m.route==='dashboard'){await refreshIdentity();go('dashboard')}else if(/^account\/(orders|prepayments)(\/[0-9a-f-]{36})?$/.test(m.route)||m.route==='account/earn')go(m.route);return}await load()})});
  function clear(){requestVersion++;status=null;messages={rows:[],total:0,unread:0};messageOffset=0;unreadOnly=false;selected='orders';queueState.forEach(s=>s.turn++);queueState.clear();for(const id of ['shoppingEarn','shoppingMessages'])document.getElementById(id)?.replaceChildren();document.getElementById('shoppingUnreadBadge')?.remove();document.querySelectorAll('.shopping-membership-queue').forEach(el=>el.remove())}
  return {load,select,queue,clear,get membership(){return status}};
 }
 window.MioShoppingNetwork={create};
})();
